class Solution:
    def findNthDigit(self, n: int) -> int:
        if n < 10:
            return n
        digit = 1
        while True:
            start = 10 ** (digit - 1)
            end = start * 10 - 1
            total_digits = (end - start + 1) * digit
            if n <= total_digits:
                break
            n -= total_digits
            digit += 1
        num = start + (n - 1) // digit
        return int(str(num)[(n - 1) % digit])

