def chessboard(s):
    n, m = map(int, s.split())
    if n == 0 or m == 0:
        return ''
    result = []
    for i in range(n):
        row = ''
        for j in range(m):
            if (i + j) % 2 == 0:
                row += '*'
            else:
                row += '.'
        result.append(row)
    return '\n'.join(result)

